const req = $json;
const body = req.body ?? {};

function bad(message) {
  return [{ json: {
    statusCode: 400,
    body: { error: 'validation_error', message }
  }}];
}

if (typeof body.customer !== 'string' || !body.customer.trim()) {
  return bad('customer is required and must be a non-empty string');
}

if (!Array.isArray(body.items) || body.items.length === 0) {
  return bad('items must contain at least one item');
}

for (let i = 0; i < body.items.length; i++) {
  const item = body.items[i];

  if (!item || typeof item.sku !== 'string' || !item.sku.trim()) {
    return bad(`items[${i}].sku is required`);
  }

  if (!Number.isInteger(item.quantity) || item.quantity <= 0) {
    return bad(`items[${i}].quantity must be a positive integer`);
  }

  if (item.price !== undefined && (typeof item.price !== 'number' || item.price < 0)) {
    return bad(`items[${i}].price must be a non-negative number`);
  }
}

const store = $getWorkflowStaticData('global');
if (!store.orders) store.orders = {};
if (!store.sequence) store.sequence = 1000;

store.sequence += 1;
const id = `ORD-${store.sequence}`;

const items = body.items.map(item => ({
  sku: item.sku.trim(),
  quantity: item.quantity,
  price: item.price ?? 100
}));

const order = {
  id,
  customer: body.customer.trim(),
  status: 'CREATED',
  currency: body.currency ?? 'RUB',
  items,
  total: items.reduce((sum, item) => sum + item.price * item.quantity, 0),
  payment: null,
  createdAt: new Date().toISOString(),
  updatedAt: new Date().toISOString()
};

store.orders[id] = order;

return [{ json: { statusCode: 201, body: order } }];

const req = $json;
const q = req.query ?? {};

const store = $getWorkflowStaticData('global');
if (!store.orders) store.orders = {};

let orders = Object.values(store.orders);

if (q.status) {
  orders = orders.filter(o => o.status === String(q.status).toUpperCase());
}

if (q.customer) {
  const s = String(q.customer).toLowerCase();
  orders = orders.filter(o => String(o.customer).toLowerCase().includes(s));
}

orders.sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)));

const offset = Math.max(0, parseInt(q.offset ?? '0', 10) || 0);
const limit = Math.min(100, Math.max(1, parseInt(q.limit ?? '20', 10) || 20));

return [{
  json: {
    statusCode: 200,
    body: {
      data: orders.slice(offset, offset + limit),
      meta: {
        total: orders.length,
        offset,
        limit
      }
    }
  }
}];

const id = $json.query?.id;

if (!id) {
  return [{ json: {
    statusCode: 400,
    body: { error: 'validation_error', message: 'Query parameter id is required' }
  }}];
}

const store = $getWorkflowStaticData('global');
if (!store.orders) store.orders = {};

const order = store.orders[id];

if (!order) {
  return [{ json: {
    statusCode: 404,
    body: { error: 'not_found', message: `Order ${id} was not found` }
  }}];
}

return [{ json: { statusCode: 200, body: order } }];

const id = $json.query?.id;
const status = String($json.body?.status ?? '').toUpperCase();
const allowed = ['CREATED', 'PROCESSING', 'PACKED', 'SHIPPED', 'DELIVERED', 'CANCELLED'];

if (!id) {
  return [{ json: {
    statusCode: 400,
    body: { error: 'validation_error', message: 'Query parameter id is required' }
  }}];
}

if (!allowed.includes(status)) {
  return [{ json: {
    statusCode: 400,
    body: { error: 'validation_error', message: 'Unsupported status', allowedStatuses: allowed }
  }}];
}

const store = $getWorkflowStaticData('global');
if (!store.orders) store.orders = {};

const order = store.orders[id];

if (!order) {
  return [{ json: {
    statusCode: 404,
    body: { error: 'not_found', message: `Order ${id} was not found` }
  }}];
}

order.status = status;
order.updatedAt = new Date().toISOString();

return [{ json: { statusCode: 200, body: order } }];

const req = $json;
const id = req.query?.id;
const scenario = String(
  req.query?.scenario ??
  req.headers?.['x-mock-scenario'] ??
  'success'
).toLowerCase();

const allowedScenarios = ['success', 'declined', 'server-error', 'timeout'];

if (!id) {
  return [{ json: {
    statusCode: 400,
    body: { error: 'validation_error', message: 'Query parameter id is required' }
  }}];
}

if (!allowedScenarios.includes(scenario)) {
  return [{ json: {
    statusCode: 400,
    body: {
      error: 'validation_error',
      message: `Unknown scenario: ${scenario}`,
      allowedScenarios
    }
  }}];
}

const store = $getWorkflowStaticData('global');
if (!store.orders) store.orders = {};
const order = store.orders[id];

if (!order) {
  return [{ json: {
    statusCode: 404,
    body: { error: 'not_found', message: `Order ${id} was not found` }
  }}];
}

if (scenario === 'timeout') {
  await new Promise(resolve => setTimeout(resolve, 3000));
  return [{ json: {
    statusCode: 504,
    body: {
      error: 'gateway_timeout',
      message: 'Mock payment provider did not answer within 3000 ms',
      retryable: true
    }
  }}];
}

if (scenario === 'declined') {
  return [{ json: {
    statusCode: 402,
    body: {
      error: 'payment_declined',
      code: 'CARD_DECLINED',
      message: 'Payment was declined by issuer',
      retryable: false
    }
  }}];
}

if (scenario === 'server-error') {
  return [{ json: {
    statusCode: 500,
    body: {
      error: 'internal_error',
      message: 'Mock payment provider failed',
      traceId: `trace-${Date.now()}-${Math.random().toString(16).slice(2)}`
    }
  }}];
}

const payment = {
  paymentId: `PAY-${Math.floor(100000 + Math.random() * 900000)}`,
  status: 'PAID',
  paidAt: new Date().toISOString(),
  amount: order.total,
  currency: order.currency
};

order.payment = payment;
order.status = 'PAID';
order.updatedAt = new Date().toISOString();

return [{ json: {
  statusCode: 200,
  body: { orderId: id, ...payment }
}}];

const store = $getWorkflowStaticData('global');
store.orders = {};
store.sequence = 1000;

return [{
  json: {
    statusCode: 200,
    body: { ok: true, message: 'Mock storage has been reset' }
  }
}];
